<?php
require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');$q='';$sql="SELECT l.*,u.full_name person FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id WHERE 1";$p=[];if($q!==''){$sql.=' AND (l.action LIKE ? OR l.details LIKE ? OR u.full_name LIKE ? OR l.ip_address LIKE ?)';$like='%'.$q.'%';$p=[$like,$like,$like,$like];}$sql.=' ORDER BY l.created_at DESC LIMIT 500';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activity Logs</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Audit trail</div><h1>Activity logs.</h1></div></header><section class="card table-wrap" data-live-scope><div class="live-filter-bar"><label class="field live-search-field">Search logs<input class="search" type="search" data-live-search placeholder="Search user, action, details or IP..."></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><table class="table"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody data-live-list><tr data-live-empty class="live-empty" hidden><td colspan="5">No activity matches your search.</td></tr><?php foreach($rows as $r):?><tr data-live-item data-search="<?=e(strtolower(($r['person']??'System').' '.$r['action'].' '.$r['details'].' '.$r['ip_address'].' '.$r['created_at']))?>"><td><?=date('M j, Y g:i A',strtotime($r['created_at']))?></td><td><?=e($r['person']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach?></tbody></table></section></main></div><script src="../assets/js/script.js"></script></body></html>
